def solve(inputs: dict) -> float:
    def pick(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        return None

    x = pick('X', 'x', 's', 'initial', 'start', 'seed', 'value')
    rounds = pick('rounds', 'times', 'iterations', 'n', 'count', 'updates')
    a = pick('a', 'multiplier', 'mult', 'coefficient')
    c = pick('c', 'increment', 'addend', 'offset')
    m = pick('m', 'modulus', 'mod')
    x, rounds, a, c, m = map(int, (x, rounds, a, c, m))
    for _ in range(rounds):
        x = (a * x + c) % m
    return float(x)

