def solve(inputs: dict) -> float:
    def pick(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        return None

    rems = pick('remainders', 'REMS', 'rems', 'residues', 'a')
    mods = pick('moduli', 'MODS', 'mods', 'm')
    rems = list(map(int, rems))
    mods = list(map(int, mods))
    x = 0
    product = 1
    for r, modulus in zip(rems, mods):
        r %= modulus
        g = __import__('math').gcd(product, modulus)
        if (r - x) % g:
            raise ValueError('Inconsistent congruences')
        reduced_modulus = modulus // g
        if reduced_modulus == 1:
            t = 0
        else:
            t = ((r - x) // g * pow(product // g, -1, reduced_modulus)) % reduced_modulus
        x += product * t
        product *= reduced_modulus
        x %= product
    return float(x)

